    s.append(".ba{max-width:85%;padding:9px 12px;border-radius:14px;background:rgba(30,41,59,.7);color:#f1f5f9;border:1px solid rgba(165,180,252,.15);border-bottom-left-radius:4px;word-wrap:break-word;}");
    s.append(".be{max-width:85%;padding:9px 12px;border-radius:14px;background:rgba(127,29,29,.45);color:#fecaca;border:1px solid rgba(248,113,113,.5);border-bottom-left-radius:4px;word-wrap:break-word;}");
